import "server-only";
import { headers } from "next/headers";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type AuthUser = { id: string; email: string; name: string; createdAt: Date | string };

function toUser(u: AuthUser): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: new Date(u.createdAt).toISOString().slice(0, 10),
  };
}

// Users are owned by Better Auth (the `user` table in the auth database).
const adapter = async () => (await auth.$context).internalAdapter;

export async function listUsers(): Promise<User[]> {
  const rows = await (await adapter()).listUsers();
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = await (await adapter()).findUserById(id);
  return row ? toUser(row) : undefined;
}

// The signed-in user for the current request, or undefined when signed out.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  return session ? toUser(session.user) : undefined;
}
EOF
cat > src/proxy.ts <<'EOF'
import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/lib/auth";

export async function proxy(request: NextRequest) {
  const session = await auth.api.getSession({ headers: request.headers });
  if (!session) {
    const url = new URL("/sign-in", request.url);
    url.searchParams.set("next", request.nextUrl.pathname);
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*"],
};
EOF
