"use client";

import Link from "next/link";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

// Only allow same-site relative paths as post-login destinations.
function safeNext(next: string | null) {
  return next && next.startsWith("/") && !next.startsWith("//") ? next : "/dashboard";
}

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const isUp = mode === "sign-up";

  function destination() {
    return safeNext(new URLSearchParams(window.location.search).get("next"));
  }

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");
    setPending(true);
    const f = new FormData(e.currentTarget);
    const email = String(f.get("email"));
    const password = String(f.get("password"));
    const { error } = isUp
      ? await authClient.signUp.email({ email, password, name: String(f.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    window.location.assign(destination());
  }

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isUp ? "Create account" : "Sign in"}</h1>
      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isUp && (
          <input name="name" placeholder="Name" required className="w-full rounded border p-2" />
        )}
        <input name="email" type="email" placeholder="Email" required className="w-full rounded border p-2" />
        <input
          name="password"
          type="password"
          placeholder="Password"
          minLength={8}
          required
          className="w-full rounded border p-2"
        />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button disabled={pending} className="w-full rounded bg-foreground p-2 text-background">
          {isUp ? "Sign up" : "Sign in"}
        </button>
      </form>
      <button
        type="button"
        className="mt-3 w-full rounded border p-2"
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: destination() })}
      >
        Continue with Google
      </button>
      <p className="mt-4 text-sm">
        {isUp ? (
          <>Have an account? <Link className="underline" href="/sign-in">Sign in</Link></>
        ) : (
          <>New here? <Link className="underline" href="/sign-up">Create an account</Link></>
        )}
      </p>
    </main>
  );
}
EOF
